const require_index = require("../useMediaQuery/index.js");
//#region src/usePreferredColorScheme/index.ts
const usePreferredColorScheme = (defaultState = "no-preference") => {
	const isLight = require_index.useMediaQuery("(prefers-color-scheme: light)", false);
	return require_index.useMediaQuery("(prefers-color-scheme: dark)", false) ? "dark" : isLight ? "light" : defaultState;
};
//#endregion
exports.usePreferredColorScheme = usePreferredColorScheme;
